UPDATE `translate_interface` SET `value` = 'Purchase type. Can take values:<br/>                  <ul>                      <li><b>''in stock''</b> - the item is in stock at least at one of the selected warehouses</li>                      <li><b>''on the way''</b> - the item is in the nearest delivery to the warehouse :default_stock</li>                      <li><b>''on request''</b> - the goods can be brought to the warehouse :default_stock on request. <b>Special payment terms</b> - check with the manager.</li>                  </ul>' WHERE
UPDATE `translate_interface` SET `value` = 'Type d''achat. Peut prendre les valeurs:<br/> <ul> <li><b>''en stock''</b> - l''article est en stock au moins dans l''un des entrepôts sélectionnés</li> <li><b>'' en route''</b> - l''article est dans la livraison la plus proche de l''entrepôt :default_stock</li> <li><b>''sur demande''</b> - les marchandises peuvent être amenées à l''entrepôt :default_stock sur demande. <b>Conditions particulières de paiement</b> - à vérifier auprès du responsable.</li> </ul>' WHERE
UPDATE `translate_interface` SET `value` = 'Тип закупки. Может принимать значения:<br/>                 <ul>                     <li><b>''в наличии''</b> - товар есть в наличиие хотя бы на одном из выбраных складов</li>                     <li><b>''в пути''</b> - товар есть в ближайшей поставке на :default_stock</li>                     <li><b>''под заказ''</b> - товар можно привезти на склад :default_stock под заказ. <b>Действуют особые условия оплаты</b> - уточняйте у менеджера.</li>                 </ul>' WHERE
